"""Generate supabase/seed/009_reference_types_seed.sql from data/reference/public-types.json (idempotent upsert)."""
import json, sys
src = sys.argv[1] if len(sys.argv) > 1 else "data/reference/public-types.json"; out = sys.argv[2] if len(sys.argv) > 2 else "supabase/seed/009_reference_types_seed.sql"
T = json.load(open(src))["types"]
cols = ["id","name","aliases","typology_system","category","period","dates","continent","country","admin1","region_notes","length_mm","width_mm","thickness_mm","pidba","traits","similar","validity","texas","home_priority","sources"]
cols = [("similar_types" if c == "similar" else c) for c in cols]
rows = [{k: t.get("similar" if k == "similar_types" else k) for k in cols} for t in T]
for r in rows:
    for k in ("aliases", "country", "admin1", "traits", "similar_types"): r[k] = r[k] or []
    r["category"] = r["category"] or "artifact"; r["home_priority"] = r["home_priority"] or 3; r["texas"] = bool(r["texas"])
payload = json.dumps(rows, ensure_ascii=False).replace("$ref$", "")
sql = f"""-- generated by tools/reference/gen_seed_sql.py from {src} ({len(rows)} rows). Run after 009_reference_types.sql.
insert into public.reference_types ({", ".join(cols)})
select x.id, x.name, coalesce(x.aliases,'{{}}'), x.typology_system, x.category, x.period, x.dates, x.continent, coalesce(x.country,'{{}}'), coalesce(x.admin1,'{{}}'), x.region_notes,
       x.length_mm, x.width_mm, x.thickness_mm, x.pidba, coalesce(x.traits,'{{}}'), coalesce(x.similar_types,'{{}}'), x.validity, x.texas, x.home_priority, x.sources
from jsonb_populate_recordset(null::public.reference_types, $ref${payload}$ref$::jsonb) x
on conflict (id) do update set name = excluded.name, aliases = excluded.aliases, typology_system = excluded.typology_system, period = excluded.period, dates = excluded.dates,
  continent = excluded.continent, country = excluded.country, admin1 = excluded.admin1, region_notes = excluded.region_notes, length_mm = excluded.length_mm, width_mm = excluded.width_mm,
  thickness_mm = excluded.thickness_mm, pidba = excluded.pidba, traits = excluded.traits, similar_types = excluded.similar_types, validity = excluded.validity, texas = excluded.texas,
  home_priority = excluded.home_priority, sources = excluded.sources, updated_at = now();
"""
open(out, "w").write(sql); print(out, len(rows))
